(6469526, 960995, 54833, '<td valign="top">Wow, don''t think I have ever seen anything quite like that!</td>', 'Wow, don''t think I have ever seen anything quite like that!', '2011-07-13 13:40:25.000000', NULL, 1),
(6469529, 961911, 54833, '<td valign="top">Nice find!</td>', 'Nice find!', '2011-07-13 13:41:20.000000', NULL, 1),
(6469530, 961458, 62094, '<td valign="top">...is this bug alive?..</td>', '...is this bug alive?..', '2011-07-13 13:41:27.000000', NULL, 1),
(6469532, 961871, 54833, '<td valign="top">Very unique editing. Gives it a nice feel</td>', 'Very unique editing. Gives it a nice feel', '2011-07-13 13:42:02.000000', NULL, 1),
(6469539, 961458, 43774, '<td valign="top">Love the colours and DOF.</td>', 'Love the colours and DOF.', '2011-07-13 13:45:39.000000', NULL, 1),
