(6475156, 961870, 116704, '<td valign="top">humorous. This one is set apart from the others because your main subject is implied and explicit like in others.</td>', 'humorous. This one is set apart from the others because your main subject is implied and explicit like in others.', '2011-07-19 08:20:08.000000', NULL, 1),
(6475158, 961745, 116704, '<td valign="top">Great color and everything but try to think more creatively with your subject.</td>', 'Great color and everything but try to think more creatively with your subject.', '2011-07-19 08:20:45.000000', NULL, 1),
(6475160, 961947, 116704, '<td valign="top">love it. you have a hidden subject and one in the fore front. well placed and such</td>', 'love it. you have a hidden subject and one in the fore front. well placed and such', '2011-07-19 08:22:03.000000', NULL, 1),
(6475163, 961358, 116704, '<td valign="top">the thing with bugs is color. Black and white does not work so well especially when your subject is not big with lots of contrast.</td>', 'the thing with bugs is color. Black and white does not work so well especially when your subject is not big with lots of contrast.', '2011-07-19 08:25:12.000000', NULL, 1),
(6475169, 961219, 116704, '<td valign="top">the berries are distracting from your subject</td>', 'the berries are distracting from your subject', '2011-07-19 08:26:56.000000', NULL, 1),
(6475170, 961842, 116704, '<td valign="top">nice contrast make sure your subject takes up more of the picture next time</td>', 'nice contrast make sure your subject takes up more of the picture next time', '2011-07-19 08:27:21.000000', NULL, 1),
(6475172, 961867, 116704, '<td valign="top">subject needs to be larger</td>', 'subject needs to be larger', '2011-07-19 08:27:36.000000', NULL, 1),
