(6475417, 961786, 102394, '<td valign="top">Very dramatic and vibrant.  The pattern on the wings is very cool.</td>', 'Very dramatic and vibrant.  The pattern on the wings is very cool.', '2011-07-19 15:20:16.000000', NULL, 1),
(6475418, 961745, 102394, '<td valign="top">A nice shot - maybe not enough contrast?  I like that you took a different angle which brings out the colors and details that are sometimes overlooked.</td>', 'A nice shot - maybe not enough contrast?  I like that you took a different angle which brings out the colors and details that are sometimes overlooked.', '2011-07-19 15:22:04.000000', NULL, 1),
