INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6475424, 961376, 102394, '<td valign="top">LOL love the title.  The beard''s pretty cool too!</td>', 'LOL love the title.  The beard''s pretty cool too!', '2011-07-19 15:26:13.000000', NULL, 1),
(6475427, 961810, 102394, '<td valign="top">I think it''s bold to go with B&amp;W in a challenge like this.  This is a very compelling shot.  One of my favorites! 9</td>', 'I think it''s bold to go with B&W in a challenge like this.  This is a very compelling shot.  One of my favorites! 9', '2011-07-19 15:27:33.000000', NULL, 1),
(6475429, 961299, 102394, '<td valign="top">I like the crop and composition, but I think the saturation could be increased to give it more punch.  Still a nice shot.</td>', 'I like the crop and composition, but I think the saturation could be increased to give it more punch.  Still a nice shot.', '2011-07-19 15:28:35.000000', NULL, 1),
(6475431, 961231, 102394, '<td valign="top">He looks cross-eyed - a confused thinker, maybe?  It''s a great capture, nice job. 8</td>', 'He looks cross-eyed - a confused thinker, maybe?  It''s a great capture, nice job. 8', '2011-07-19 15:29:35.000000', NULL, 1),
(6475433, 961335, 102394, '<td valign="top">It''s got a kind of dark and shadowy look to it.  It''s not as sharp or bright as others, but I like the abstract feel of it.</td>', 'It''s got a kind of dark and shadowy look to it.  It''s not as sharp or bright as others, but I like the abstract feel of it.', '2011-07-19 15:31:47.000000', NULL, 1),
(6475436, 961870, 102394, '<td valign="top">This made me laugh!  Great idea, but not focused/sharp enough for me.</td>', 'This made me laugh!  Great idea, but not focused/sharp enough for me.', '2011-07-19 15:33:30.000000', NULL, 1),
(6475437, 961761, 102394, '<td valign="top">*shudder*  it has such a crisp, wintery feel to it.  Great shot. 9</td>', '*shudder*  it has such a crisp, wintery feel to it.  Great shot. 9', '2011-07-19 15:34:39.000000', NULL, 1),
(6475438, 961784, 102394, '<td valign="top">I never thought I''d say ''what a cute spider'', but... What a cute spider!!! Love the simplicity. 8</td>', 'I never thought I''d say ''what a cute spider'', but... What a cute spider!!! Love the simplicity. 8', '2011-07-19 15:35:47.000000', NULL, 1),
(6475441, 960755, 102394, '<td valign="top">How cool to see this happening!  Unfortunately, it just isn''t sharp enough, which is good for the mantis (since it blends into the background), but probably not as good in the challenge.  6</td>', 'How cool to see this happening!  Unfortunately, it just isn''t sharp enough, which is good for the mantis (since it blends into the background), but probably not as good in the challenge.  6', '2011-07-19 15:38:45.000000', NULL, 1),
(6475442, 960866, 28427, '<td valign="top">Would have preferred more sharpness on the little bugger and less on the heart of the flower, which seems to be the main subject of your photograph now.<br/>Nice colors and comp.</td>', 'Would have preferred more sharpness on the little bugger and less on the heart of the flower, which seems to be the main subject of your photograph now.Nice colors and comp.', '2011-07-19 15:40:07.000000', NULL, 1),
(6475445, 960995, 102394, '<td valign="top">Wow.  One of my favorites - one of the few that didn''t give me the creepy crawlies. 10</td>', 'Wow.  One of my favorites - one of the few that didn''t give me the creepy crawlies. 10', '2011-07-19 15:44:10.000000', NULL, 1),
(6475447, 961928, 28427, '<td valign="top">but spotted anyway - and well spotted :)</td>', 'but spotted anyway - and well spotted :)', '2011-07-19 15:44:59.000000', NULL, 1),
(6475457, 961273, 28427, '<td valign="top">Oh well...you are right: this IS a beetle and therefor should not be labeled as DNMC.  Hard to compare with the other entries though.</td>', 'Oh well...you are right: this IS a beetle and therefor should not be labeled as DNMC.  Hard to compare with the other entries though.', '2011-07-19 16:14:53.000000', NULL, 1),
(6475477, 961181, 28427, '<td valign="top">AMAZING!</td>', 'AMAZING!', '2011-07-19 16:40:01.000000', NULL, 1),
