(6475647, 961897, 64086, '<td valign="top">That''s a mean looking critter.</td>', 'That''s a mean looking critter.', '2011-07-19 19:48:06.000000', NULL, 1),
(6475660, 961892, 109227, '<td valign="top">This makes me sad.  After looking at all the colorful and happy looking bugs, this makes you realize that they are more than just bugs - it''s a life.  Your choice of processing brings this out.</td>', 'This makes me sad.  After looking at all the colorful and happy looking bugs, this makes you realize that they are more than just bugs - it''s a life.  Your choice of processing brings this out.', '2011-07-19 20:17:34.000000', NULL, 1),
(6475662, 961709, 100831, '<td valign="top">So little goes so far... there''s something I really like about this almost abstract image.. the bokeh and the desaturated color is great background to the detail. Dinner has two Ns - a Diner is where one eats - that would help -  but an 8 from me regardless.</td>', 'So little goes so far... there''s something I really like about this almost abstract image.. the bokeh and the desaturated color is great background to the detail. Dinner has two Ns - a Diner is where one eats - that would help -  but an 8 from me regardless.', '2011-07-19 20:20:59.000000', NULL, 1),
(6475664, 961675, 100831, '<td valign="top">cool. he looks MEAN</td>', 'cool. he looks MEAN', '2011-07-19 20:21:24.000000', NULL, 1),
