(6476117, 961430, 98022, '<td valign="top">Congrats on the HM! One of the most striking spider images that I have seen!</td>', 'Congrats on the HM! One of the most striking spider images that I have seen!', '2011-07-20 01:39:48.000000', NULL, 0),
(6476121, 960995, 98022, '<td valign="top">This is a cool image. Really like the patterns and textures. Great capture. Congrats on the HM!</td>', 'This is a cool image. Really like the patterns and textures. Great capture. Congrats on the HM!', '2011-07-20 01:42:03.000000', NULL, 0),
(6476122, 961360, 98022, '<td valign="top">Very nice colors and clarity. Congrats on the top 10!</td>', 'Very nice colors and clarity. Congrats on the top 10!', '2011-07-20 01:43:21.000000', NULL, 0),
(6476125, 961950, 104009, '<td valign="top">and congrats to you sir!  i am VERY honored to see my image next to an image of such incredible quality in a challenge, great work and well deserved new PB!</td>', 'and congrats to you sir!  i am VERY honored to see my image next to an image of such incredible quality in a challenge, great work and well deserved new PB!', '2011-07-20 01:45:17.000000', NULL, 0),
(6476126, 961304, 98022, '<td valign="top">One of my favorites in the challenge. Really like the colors and the detail on the insect abdomen. Congrats on the top 10 finish!</td>', 'One of my favorites in the challenge. Really like the colors and the detail on the insect abdomen. Congrats on the top 10 finish!', '2011-07-20 01:45:19.000000', NULL, 0),
(6476130, 961974, 18778, '<td valign="top">For what it''s worth- I totally dig this piece.  Made an otherwise bland challenge ( as in, most of the styles presented were the same) cool to look at.</td>', 'For what it''s worth- I totally dig this piece.  Made an otherwise bland challenge ( as in, most of the styles presented were the same) cool to look at.', '2011-07-20 01:48:06.000000', NULL, 0),
(6476134, 960778, 98022, '<td valign="top">Man! Where did you find this thing. I''ve never seen anything like this in Alabama. Great job with the macro. Congrats on the top 10 finish!<br/> <br/>And how did you get it to sit on your finger for the size illustration shot?</td>', 'Man! Where did you find this thing. I''ve never seen anything like this in Alabama. Great job with the macro. Congrats on the top 10 finish! And how did you get it to sit on your finger for the size illustration shot?', '2011-07-20 01:49:43.000000', NULL, 0),
