(6476156, 961496, 16106, '<td valign="top">Not sure how this slid so far, I had this slotted for a ribbon. I love the way you made him look like the original "Hopper".</td>', 'Not sure how this slid so far, I had this slotted for a ribbon. I love the way you made him look like the original "Hopper".', '2011-07-20 02:05:52.000000', NULL, 0),
(6476160, 961784, 16106, '<td valign="top">How this pulled anything 6 or lower is beyond me. Great framing and ....well attitude.</td>', 'How this pulled anything 6 or lower is beyond me. Great framing and ....well attitude.', '2011-07-20 02:09:54.000000', NULL, 0),
(6476162, 961957, 112828, '<td valign="top">Great colors!  The focus is spot on and the overall effect is just excellent, I suspect the border may have helped too!  Well done and congrats on the placement!</td>', 'Great colors!  The focus is spot on and the overall effect is just excellent, I suspect the border may have helped too!  Well done and congrats on the placement!', '2011-07-20 02:12:43.000000', NULL, 0),
