(6476266, 961957, 97225, '<td valign="top">Congratulations on the blue ribbon. It''s a great shot - love the colours.</td>', 'Congratulations on the blue ribbon. It''s a great shot - love the colours.', '2011-07-20 03:44:45.000000', NULL, 0),
(6476267, 960995, 83902, '<td valign="top">Oh man I never thought this photo would do so well! And I definitely didn''t think I would be achieving my goal of getting a seven on dpc with it either, but hey no complaints, even though I did get a 1 which I think is lame :(  <br/> Thank you everyone for the great comments and votes. This was taken In Yosemite National Park, CA. And Im not sure if these are Ladybugs or Asian Beetles.  And I have no idea if this is a unusual occurrence or something regular, but just thought it was awesome and had to capture it.</td>', 'Oh man I never thought this photo would do so well! And I definitely didn''t think I would be achieving my goal of getting a seven on dpc with it either, but hey no complaints, even though I did get a 1 which I think is lame :(   Thank you everyone for the great comments and votes. This was taken In Yosemite National Park, CA. And Im not sure if these are Ladybugs or Asian Beetles.  And I have no idea if this is a unusual occurrence or something regular, but just thought it was awesome and had to capture it.', '2011-07-20 03:44:55.000000', NULL, 0),
(6476286, 961350, 102534, '<td valign="top">Congratulations on a top-10 finish and a new personal best.</td>', 'Congratulations on a top-10 finish and a new personal best.', '2011-07-20 04:08:03.000000', NULL, 0),
(6476289, 961249, 102534, '<td valign="top">Great shot. Very tough competition in this challenge with so many fantastic shots.</td>', 'Great shot. Very tough competition in this challenge with so many fantastic shots.', '2011-07-20 04:09:33.000000', NULL, 0),
(6476291, 961834, 102534, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Hussar1812:</b></div><hr/><i> I liked this guy...should have done better. </i></td></tr></table> <br/> <br/>Thank you Mr Hussar. You sound just like my old high school teacher :)</td>', 'Originally posted by Hussar1812: I liked this guy...should have done better.   Thank you Mr Hussar. You sound just like my old high school teacher :)', '2011-07-20 04:10:58.000000', NULL, 0),
(6476300, 961430, 119443, '<td valign="top">Joe yeeiiii congratulations!!!This is a great image, i love it! That score is awesome! Congrats again, well deserved!</td>', 'Joe yeeiiii congratulations!!!This is a great image, i love it! That score is awesome! Congrats again, well deserved!', '2011-07-20 04:23:21.000000', NULL, 0),
