INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6476449, 961376, 135401, '<td valign="top">Thanks everyone, I really didn''t expect this pic to get such high notes, I''m happy U guys like it :) Thank U for kind comments and marks.</td>', 'Thanks everyone, I really didn''t expect this pic to get such high notes, I''m happy U guys like it :) Thank U for kind comments and marks.', '2011-07-20 06:11:28.000000', NULL, 0),
