(6476451, 961350, 93421, '<td valign="top">-Delete duplicate post-<br/><br/><i>Message edited by author 2011-07-20 11:02:25.</i></td>', '-Delete duplicate post-', '2011-07-20 06:20:42.000000', '2011-07-20 12:02:25.000000', 0),
(6476452, 961350, 93421, '<td valign="top">Congrats Old Man!!!  Top 10 and a new PB!  Keep it up!</td>', 'Congrats Old Man!!!  Top 10 and a new PB!  Keep it up!', '2011-07-20 06:20:50.000000', NULL, 0),
(6476453, 961249, 93421, '<td valign="top">I thought this might have been yours.  Nice one!  Pity about the wing</td>', 'I thought this might have been yours.  Nice one!  Pity about the wing', '2011-07-20 06:23:31.000000', NULL, 0),
(6476454, 961834, 93421, '<td valign="top">Expected this to do much better.  Nice capture!</td>', 'Expected this to do much better.  Nice capture!', '2011-07-20 06:24:58.000000', NULL, 0),
(6476455, 961957, 114565, '<td valign="top">Congrats on the Bluey.<br/>Just wondering, I have just brought into the world of macro with the Nikon 60mm 2.8D, was this shot taken with just that or extensions too?<br/>Just want to know as I am new to macro and am fascinated by the whole thing.<br/>This is an awesome image, Well done!</td>', 'Congrats on the Bluey.Just wondering, I have just brought into the world of macro with the Nikon 60mm 2.8D, was this shot taken with just that or extensions too?Just want to know as I am new to macro and am fascinated by the whole thing.This is an awesome image, Well done!', '2011-07-20 06:29:19.000000', NULL, 0),
(6476456, 961740, 60173, '<td valign="top">I sure am glad you went with this rather than the bee. I knew people would appreciate the difficulty of getting a clear dragonfly shot.</td>', 'I sure am glad you went with this rather than the bee. I knew people would appreciate the difficulty of getting a clear dragonfly shot.', '2011-07-20 06:37:15.000000', NULL, 0),
(6476458, 961957, 135401, '<td valign="top">Congrats mate! I have to admit it was one of my picks for blue :) Nice shot.</td>', 'Congrats mate! I have to admit it was one of my picks for blue :) Nice shot.', '2011-07-20 06:37:32.000000', NULL, 0),
(6476459, 961957, 20608, '<td valign="top">Well look at you all dressed in BLUE, many congrats</td>', 'Well look at you all dressed in BLUE, many congrats', '2011-07-20 06:45:28.000000', NULL, 0),
(6476460, 961430, 60173, '<td valign="top">Man, look at you! Very nicely done.</td>', 'Man, look at you! Very nicely done.', '2011-07-20 06:45:52.000000', NULL, 0),
(6476465, 960820, 113591, '<td valign="top">Wife no 3?</td>', 'Wife no 3?', '2011-07-20 07:03:36.000000', NULL, 0),
