(6476467, 961794, 113591, '<td valign="top">Made me remember about facing new territory.</td>', 'Made me remember about facing new territory.', '2011-07-20 07:09:42.000000', NULL, 0),
(6476468, 961350, 68956, '<td valign="top">Beautiful lighting, it''s all too easy to catch harsh highlights on insects (plenty of examples of that in this competition) Choosing your location in respect to direct light can give great results like this :)</td>', 'Beautiful lighting, it''s all too easy to catch harsh highlights on insects (plenty of examples of that in this competition) Choosing your location in respect to direct light can give great results like this :)', '2011-07-20 07:11:06.000000', NULL, 0),
(6476471, 961966, 113591, '<td valign="top">definitely food <strike>for thought</strike></td>', 'definitely food for thought', '2011-07-20 07:12:13.000000', NULL, 0),
(6476487, 961872, 103032, '<td valign="top">I thought your dragonfly was pretty well captured.  I gave this a 7.  Just my opinion, but if you had captured it from the front side, I think it would have scored much higher.  It''s all about eye contact :)</td>', 'I thought your dragonfly was pretty well captured.  I gave this a 7.  Just my opinion, but if you had captured it from the front side, I think it would have scored much higher.  It''s all about eye contact :)', '2011-07-20 07:56:52.000000', NULL, 0),
